  "range_high": 0.05,
  "summary": [
    "Posterior probability of any party achieving a 2/3 majority in 2026 Hungary is calibrated at 3%.",
    "Key updates from polls show opposition consolidation and Tisza leads, depressing odds for a 2/3 majority.",
    "Seat projections sit near but below the 133-seat threshold, further reducing likelihood.",
    "Structural factors like districting provide upside risk, while turnout and third-party dynamics introduce uncertainty; overall assessment remains conservative."
  ],
  "confidence": "low",
  "narrative": "Starting from a historical baseline for a 2/3 majority, credible updates from late-2025 to early-2026 polling and consolidation push the probability down to about 3%, with districting offering limited upside and turnout/third-party dynamics introducing additional uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "historical base rate of two-thirds majorities in Hungary (4 of 9 elections since 1990) providing a baseline prior before 2026 updates."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation behind Tisza",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "uniting opposition reduces fragmentation and increases anti-Fidesz seat prospects, lowering chance of a 2/3 majority."
      },
      {
        "factor": "Tisza polling lead vs Fidesz (Jan–Feb 2026)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "polls show Tisza ahead or near parity; reduces probability of a single-party 2/3 majority."
      },
      {
        "factor": "Seat projections near but below the 2/3 threshold",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Real-PR and other models project around 64% of seats for Fidesz-KDNP, well shy of 133 seats."
      },
      {
        "factor": "Gerrymandered districts advantaging Fidesz",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "district-level biases can boost seat share beyond national vote, adding upside risk."
      },
      {
        "factor": "Our Homeland crossing threshold and vote-splitting",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "MH party may siphon votes and complicate anti-Fidesz consolidation."
      },
      {
        "factor": "Turnout dynamics favoring opposition mobilization",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "higher turnout among Tisza supporters could reduce Fidesz seat share."
      },
      {
        "factor": "Market signals of political change",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "forint appreciation expectations signal shift away from incumbents."
      }
    ],
    "synthesis_rationale": "The base rate implies non-negligible probability of a 2/3 majority, but the majority of credible updates shift probability downward. An upside from districting is acknowledged but insufficient to raise the posterior meaningfully above a few percent; the 3% figure reflects correlated factors and limited independence."
  }
}

